import {LAND,PIER,YARD,BUILDINGS,COVERS,STATIONS,WEAPONS,ARMORS,RECIPES,CRATES,DESTINATIONS,PALETTES,SKINS,LOOK_LIMITS,LOOK_DEFAULTS} from './data.js';
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function inside(x,y,poly=LAND){let c=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++)if((poly[i][1]>y)!==(poly[j][1]>y)&&x<(poly[j][0]-poly[i][0])*(y-poly[i][1])/(poly[j][1]-poly[i][1])+poly[i][0])c=!c;return c;}
export function rect(x,y,b,r=0){return x>b.x-r&&x<b.x+b.w+r&&y>b.y-r&&y<b.y+b.h+r;}
export function walkable(x,y,r=13){for(let [dx,dy]of [[r,0],[-r,0],[0,r],[0,-r]])if(!inside(x+dx,y+dy)&&!rect(x+dx,y+dy,PIER))return false;return !BUILDINGS.some(b=>rect(x,y,b,r))&&!COVERS.some(b=>rect(x,y,b,r));}
export function moveBody(p,dx,dy,bounded=false){let steps=Math.max(1,Math.ceil(Math.hypot(dx,dy)/8));for(let i=0;i<steps;i++){let x=p.x+dx/steps,y=p.y+dy/steps;const valid=(x,y)=>walkable(x,y,p.r||13)&&(!bounded||rect(x,y,{x:YARD.x+18,y:YARD.y+18,w:YARD.w-36,h:YARD.h-36}));if(valid(x,p.y))p.x=x;if(valid(p.x,y))p.y=y;}}
export class Hollow {
 constructor(){this.p={x:1510,y:1480,r:13,hp:100,angle:0,dash:0,dashTime:0,invuln:0};this.look={...LOOK_DEFAULTS};this.weapon='pistol';this.armor='scout';this.owned=['scout'];this.upgrades={pistol:0,carbine:0,shotgun:0,marksman:0};this.materials={scrap:24,cloth:12,herb:8,parts:9,alloy:5};this.tonics=3;this.collected=[];this.allowance=false;this.records={drills:0,best:0};this.clip=12;this.reloadTime=0;this.cooldown=0;this.bullets=[];this.enemies=[];this.effects=[];this.events=[];this.drill=null;this.lastReport=null;this.time=0;this.id=0;this.stats={shots:0,hits:0,damage:0,kills:0};this.dummies=[3420,3570,3800].map((x,i)=>({id:'dummy'+i,x,y:2220,r:19,hp:200,flash:0,respawn:0}));}
 emit(type,data={}){this.events.push({type,...data});}
 get inYard(){return rect(this.p.x,this.p.y,YARD);}
 get gun(){return WEAPONS[this.weapon];}
 equip(id){if(this.drill)return false;if(WEAPONS[id]){this.weapon=id;this.clip=this.gun.clip;this.reloadTime=0;this.cooldown=0;return true;}if(ARMORS[id]&&this.owned.includes(id)){this.armor=id;return true;}return false;}
 setLook(k,n){let max=LOOK_LIMITS[k];if(!max||!Number.isInteger(n)||n<0||n>=max)return false;this.look[k]=n;return true;}
 nearest(){let items=[...STATIONS,...CRATES.filter(c=>!this.collected.includes(c.id)).map(c=>({...c,label:'Salvage cache',kind:'crate'}))];return items.filter(s=>distance(s,this.p)<105).sort((a,b)=>distance(a,this.p)-distance(b,this.p))[0]||null;}
 collect(id){let c=CRATES.find(c=>c.id===id);if(!c||this.collected.includes(id)||distance(c,this.p)>110||this.drill)return false;for(let [k,v]of Object.entries(c.loot))this.materials[k]+=v;this.collected.push(id);this.emit('loot',{loot:c.loot});return true;}
 craft(id){if(this.drill)return {ok:false,message:'Finish the drill first.'};let r=RECIPES.find(r=>r.id===id);if(!r)return {ok:false,message:'Unknown recipe.'};if(this.owned.includes(id)||(r.weapon&&this.upgrades[r.weapon]>=3)||(id==='tonic'&&this.tonics>=6))return {ok:false,message:'Already at capacity.'};let tier=r.weapon?this.upgrades[r.weapon]+1:1;for(let [k,n]of Object.entries(r.cost))if(this.materials[k]<n*tier)return {ok:false,message:'More materials needed.'};for(let [k,n]of Object.entries(r.cost))this.materials[k]-=n*tier;if(id==='tonic')this.tonics++;else if(r.weapon)this.upgrades[r.weapon]++;else{this.owned.push(id);this.armor=id;}this.emit('craft');return {ok:true,message:id==='tonic'?'Tonic prepared.':r.weapon?'Weapon improved.':'Armor crafted and equipped.'};}
 allowanceClaim(){if(this.allowance)return false;this.allowance=true;for(let [k,n]of Object.entries({scrap:12,cloth:5,herb:4,parts:3}))this.materials[k]+=n;return true;}
 dash(mx,my){if(this.p.dash>0)return false;let d=Math.hypot(mx,my);this.p.dx=d>.1?mx/d:Math.cos(this.p.angle);this.p.dy=d>.1?my/d:Math.sin(this.p.angle);this.p.dash=2.8;this.p.dashTime=.16;this.p.invuln=.25;this.emit('dash');return true;}
 heal(){if(this.p.hp>=100||this.tonics<=0)return false;this.tonics--;this.p.hp=Math.min(100,this.p.hp+55);this.emit('heal');return true;}
 reload(){if(this.reloadTime>0||this.clip>=this.gun.clip)return false;this.reloadTime=this.gun.reload;return true;}
 travel(i){if(this.drill||!DESTINATIONS[i])return false;let d=DESTINATIONS[i];this.p.x=d.x;this.p.y=d.y;this.bullets=[];return true;}
 resetTargets(){this.stats={shots:0,hits:0,damage:0,kills:0};for(let d of this.dummies){d.hp=200;d.respawn=0;}}
 startDrill(mode='standard'){if(this.drill)return false;this.drill={mode,elapsed:0,spawned:0,total:mode==='swarm'?28:mode==='gentle'?8:16,timer:2};this.p.x=3480;this.p.y=2650;this.p.hp=100;this.p.invuln=2;this.p.dash=0;this.p.dashTime=0;this.savedTonics=this.tonics;this.tonics=3;this.clip=this.gun.clip;this.reloadTime=0;this.bullets=[];this.enemies=[];this.effects=[];this.resetTargets();this.emit('drillStart');return true;}
 endDrill(result='stopped'){if(!this.drill)return false;let drill=this.drill;this.lastReport={...this.stats,result,mode:drill.mode,time:drill.elapsed};if(result==='complete'){this.records.drills++;this.records.best=Math.max(this.records.best,this.stats.kills);this.materials.scrap+=6;this.materials.herb+=2;this.materials.parts+=1;}this.tonics=this.savedTonics;this.drill=null;this.enemies=[];this.bullets=[];this.p.hp=100;this.p.x=3320;this.p.y=2630;this.p.dashTime=0;this.clip=this.gun.clip;this.reloadTime=0;this.emit('report',this.lastReport);return true;}
 hit(e,damage,bullet){if(e.hp<=0)return;let amount=Math.min(e.hp,damage);e.hp-=damage;e.flash=.12;this.stats.damage+=amount;if(!bullet.credited){this.stats.hits++;bullet.credited=true;}this.effects.push({x:e.x,y:e.y,value:Math.round(damage),life:.65});if(e.hp<=0){if(typeof e.id==='string')e.respawn=2;else{this.stats.kills++;this.emit('kill');}}}
 fire(){if(!this.inYard||this.reloadTime>0||this.cooldown>0)return;if(this.clip<=0){this.reload();return;}let w=this.gun;this.clip--;this.cooldown=w.rate;this.stats.shots++;let shotId=++this.id;for(let i=0;i<w.pellets;i++){let a=this.p.angle+(w.pellets===1?Math.sin(this.time*123)*w.spread:(i/(w.pellets-1)-.5)*w.spread*2);this.bullets.push({id:++this.id,shotId,x:this.p.x+Math.cos(a)*19,y:this.p.y+Math.sin(a)*19,vx:Math.cos(a)*w.speed,vy:Math.sin(a)*w.speed,life:w.range/w.speed,damage:w.damage*(1+this.upgrades[this.weapon]*.15),credited:false});}this.emit('shot');if(this.clip===0)this.reload();}
 update(dt,input={}){dt=clamp(dt,0,.05);this.time+=dt;let p=this.p;p.dash=Math.max(0,p.dash-dt);p.invuln=Math.max(0,p.invuln-dt);this.cooldown=Math.max(0,this.cooldown-dt);if(this.reloadTime>0){this.reloadTime-=dt;if(this.reloadTime<=0){this.clip=this.gun.clip;this.reloadTime=0;}}let mx=input.mx||0,my=input.my||0,l=Math.hypot(mx,my);if(l>1){mx/=l;my/=l;}this.moving=Math.hypot(mx,my)>.1;if(Number.isFinite(input.angle))p.angle=input.angle;
 if(p.dashTime>0){p.dashTime-=dt;moveBody(p,p.dx*650*dt,p.dy*650*dt,!!this.drill);}else moveBody(p,mx*ARMORS[this.armor].speed*dt,my*ARMORS[this.armor].speed*dt,!!this.drill);if(input.fire)this.fire();
 let d=this.drill;if(d){d.elapsed+=dt;d.timer-=dt;if(d.spawned<d.total&&d.timer<=0&&this.enemies.length<12){let heavy=d.spawned%7===6,runner=d.spawned%3===2;this.enemies.push({id:++this.id,x:3340+(d.spawned*173)%500,y:2180,r:heavy?22:14,hp:heavy?185:runner?45:75,max:heavy?185:runner?45:75,speed:heavy?50:runner?108:68,type:heavy?'brute':runner?'runner':'shambler',flash:0,attack:0});d.spawned++;d.timer=d.mode==='swarm'?.7:1.5;}}
 for(let e of this.enemies){e.flash=Math.max(0,e.flash-dt);e.attack-=dt;if(e.hp<=0)continue;let dx=p.x-e.x,dy=p.y-e.y,n=Math.hypot(dx,dy)||1;let ox=e.x,oy=e.y;moveBody(e,dx/n*e.speed*dt,dy/n*e.speed*dt,true);if(Math.hypot(e.x-ox,e.y-oy)<e.speed*dt*.3){let sign=e.id%2?1:-1;moveBody(e,-dy/n*e.speed*dt*sign,dx/n*e.speed*dt*sign,true);}for(let other of this.enemies){if(other===e||other.hp<=0)continue;let dd=distance(e,other);if(dd>0&&dd<e.r+other.r)moveBody(e,(e.x-other.x)/dd*25*dt,(e.y-other.y)/dd*25*dt,true);}if(distance(e,p)<e.r+16&&e.attack<=0&&p.invuln<=0){p.hp-=Math.max(2,(e.type==='brute'?23:12)-ARMORS[this.armor].protection)*(d?.mode==='gentle'?.6:1);p.invuln=.6;e.attack=.8;this.emit('hurt');}}
 let hitShots=new Set();for(let b of this.bullets){let steps=Math.max(1,Math.ceil(Math.hypot(b.vx,b.vy)*dt/10));for(let i=0;i<steps&&b.life>0;i++){b.x+=b.vx*dt/steps;b.y+=b.vy*dt/steps;b.life-=dt/steps;if(!rect(b.x,b.y,YARD)||COVERS.some(c=>rect(b.x,b.y,c))){b.life=0;break;}let target=(this.drill?this.enemies:this.dummies).find(e=>e.hp>0&&distance(e,b)<e.r+3);if(target){b.credited=this.shotHits?.has(b.shotId)||hitShots.has(b.shotId);this.hit(target,b.damage,b);hitShots.add(b.shotId);b.life=0;}}}this.shotHits??=new Set();for(let id of hitShots)this.shotHits.add(id);if(this.shotHits.size>500)this.shotHits=new Set([...this.shotHits].slice(-100));
 for(let target of this.dummies){target.flash=Math.max(0,target.flash-dt);if(target.respawn>0){target.respawn-=dt;if(target.respawn<=0)target.hp=200;}}
 this.bullets=this.bullets.filter(b=>b.life>0);this.enemies=this.enemies.filter(e=>e.hp>0);for(let fx of this.effects)fx.life-=dt;this.effects=this.effects.filter(f=>f.life>0).slice(-40);
 if(this.drill&&p.hp<=0)this.endDrill('downed');else if(this.drill&&this.drill.spawned>=this.drill.total&&!this.enemies.length)this.endDrill('complete');
 }
 snapshot(){return JSON.parse(JSON.stringify({version:3,appearanceVersion:2,p:{x:this.drill?3320:this.p.x,y:this.drill?2630:this.p.y,hp:this.drill?100:this.p.hp},look:this.look,weapon:this.weapon,armor:this.armor,owned:this.owned,upgrades:this.upgrades,materials:this.materials,tonics:this.drill?this.savedTonics:this.tonics,collected:this.collected,allowance:this.allowance,records:this.records}));}
 static restore(d){if(!d||d.version!==3)throw Error('Unrecognized save');let g=new Hollow();for(let k of ['weapon','armor'])if((k==='weapon'?WEAPONS:ARMORS)[d[k]])g[k]=d[k];let look={...d.look};if(d.appearanceVersion!==2&&look.hair>=2&&look.hair<=4){look.headwear=look.hair-1;look.hair=0;}for(let k of Object.keys(LOOK_LIMITS))g.setLook(k,look[k]);g.owned=['scout',...['woven','plated'].filter(k=>d.owned?.includes(k))];if(!g.owned.includes(g.armor))g.armor='scout';for(let k in g.materials)if(Number.isFinite(d.materials?.[k]))g.materials[k]=clamp(Math.floor(d.materials[k]),0,99999);for(let k in g.upgrades)g.upgrades[k]=clamp(Math.floor(d.upgrades?.[k]||0),0,3);g.tonics=clamp(Math.floor(d.tonics??3),0,6);g.collected=CRATES.filter(c=>d.collected?.includes(c.id)).map(c=>c.id);g.allowance=!!d.allowance;g.records={drills:Math.max(0,Number(d.records?.drills)||0),best:Math.max(0,Number(d.records?.best)||0)};if(Number.isFinite(d.p?.x)&&Number.isFinite(d.p?.y)&&walkable(d.p.x,d.p.y)){g.p.x=d.p.x;g.p.y=d.p.y;}g.p.hp=clamp(Number(d.p?.hp)||100,1,100);g.clip=g.gun.clip;return g;}
}
